node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createClient } from './src/client.mjs';
import { delayFor, shouldRetry } from './src/policy.mjs';

let generated = 0;
const seen = [];
const delays = [];
const request = createClient({
  transport: async req => {
    seen.push(req);
    return { status: seen.length === 1 ? 503 : 200, headers: seen.length === 1 ? { 'Retry-After': '1.25' } : {} };
  },
  sleep: async ms => delays.push(ms),
  keyFactory: () => `key-${++generated}`,
  maxAttempts: 3,
});
assert.equal((await request({ method: 'POST', url: '/x', headers: { authorization: 'token' } })).status, 200);
assert.deepEqual(delays, [1250]);
assert.equal(generated, 1);
assert.equal(seen[0].headers['idempotency-key'], 'key-1');
assert.equal(seen[1].headers['idempotency-key'], 'key-1');
assert.equal(seen[0].headers.authorization, 'token');
await request({ method: 'POST', url: '/x' });
assert.equal(seen[2].headers['idempotency-key'], 'key-2');
let called = false;
const explicit = createClient({ transport: async req => { assert.equal(req.headers['Idempotency-Key'], 'caller'); return { status: 200 }; }, sleep: async () => {}, keyFactory: () => { called = true; } });
await explicit({ method: 'POST', url: '/x', headers: { 'Idempotency-Key': 'caller' } });
assert.equal(called, false);
assert.equal(delayFor({ headers: { 'retry-after': '2' } }, 2, 100), 2000);
assert.equal(delayFor({ headers: { 'retry-after': 'invalid' } }, 2, 100), 200);
assert.equal(shouldRetry({ status: 599 }), true);
assert.equal(shouldRetry({ status: 600 }), false);
assert.equal(shouldRetry({ status: 404 }), false);
console.log('additional contract checks passed');
EOF

