patches.after:
function getHeader(headers, name) {
  if (!headers) return undefined;
  if (typeof headers.get === 'function') return headers.get(name);

  const key = Object.keys(headers).find(headerName => headerName.toLowerCase() === name);
  return key === undefined ? undefined : headers[key];
}

export function delayFor(response, attempt, baseMs) {
  const retryAfter = getHeader(response.headers, 'retry-after');
  const seconds = typeof retryAfter === 'number'
    ? retryAfter
    : typeof retryAfter === 'string' && retryAfter.trim() !== ''
      ? Number(retryAfter)
      : NaN;

  if (Number.isFinite(seconds) && seconds >= 0) return seconds * 1000;
  return baseMs * 2 ** (attempt - 1);
}

export function shouldRetry(response) {
  const status = response?.status;
  return status === 429 || (Number.isInteger(status) && status >= 500 && status <= 599);
}
